const configuredApi=new URL(self.location.href).searchParams.get('api')||'';const api=configuredApi&&new URL(configuredApi).protocol==='https:'?new URL(configuredApi).origin:self.location.origin;
self.addEventListener('push',event=>{event.waitUntil((async()=>{let p;try{p=event.data.json()}catch{return}await self.registration.showNotification(p.title||'Ясна',{body:p.body||'',tag:p.tag||'yasna',icon:'./yasna-logo-light.png',data:{url:'/'}});if(p.receiptToken)await fetch(api+'/api/push/delivered',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:p.receiptToken}),credentials:'same-origin'}).catch(()=>{})})())});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const pages=await clients.matchAll({type:'window',includeUncontrolled:true});if(pages.length)return pages[0].focus();return clients.openWindow('./')})())});
